package mg.lagrace.api.leave.application;
import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
import org.springframework.jdbc.core.namedparam.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import mg.lagrace.api.auth.User; import mg.lagrace.api.auth.persistence.UserRepository; import mg.lagrace.api.employee.*; import mg.lagrace.api.employee.persistence.*; import mg.lagrace.api.exceptions.*; import mg.lagrace.api.leave.LeaveRequest; import mg.lagrace.api.leave.dto.LeaveDtos.*; import mg.lagrace.api.leave.persistence.LeaveRepository;
@Service public class LeaveService {
 private final LeaveRepository leaves; private final EmployeeRepository employees; private final LeaveTypeRepository types; private final UserRepository users; private final Clock clock; private final NamedParameterJdbcTemplate jdbc;
 public LeaveService(LeaveRepository l,EmployeeRepository e,LeaveTypeRepository t,UserRepository u,Clock c,NamedParameterJdbcTemplate j){leaves=l;employees=e;types=t;users=u;clock=c;jdbc=j;}
 public List<TypeResponse> types(){return types.findAll().stream().map(t->new TypeResponse(t.getIdLeaveType(),t.getName())).toList();}
 public TypeResponse createType(TypeRequest r){String n=name(r.name()); if(types.existsByName(n))throw new DuplicateResourceException("Ce type de congé existe déjà."); LeaveType t=new LeaveType();t.setName(n);t=types.save(t);return new TypeResponse(t.getIdLeaveType(),t.getName());}
 public TypeResponse renameType(Long id,TypeRequest r){LeaveType t=type(id);String n=name(r.name());if(!t.getName().equals(n)&&types.existsByName(n))throw new DuplicateResourceException("Ce type de congé existe déjà.");t.setName(n);return new TypeResponse(t.getIdLeaveType(),t.getName());}
 public void deleteType(Long id){if(leaves.existsByLeaveTypeIdLeaveType(id))throw new ConflictException("LEAVE_TYPE_IN_USE","Ce type de congé est déjà utilisé.");types.delete(type(id));}
 @Transactional public Item create(Create r,Authentication a){validate(r.startDate(),r.endDate(),r.notes()); Employee e=employee(r.employeeId()); LeaveType t=type(r.leaveTypeId()); overlap(e.getIdEmployee(),r.startDate(),r.endDate(),null); LeaveRequest l=new LeaveRequest();l.setEmployee(e);l.setLeaveType(t);l.setStartDate(r.startDate());l.setEndDate(r.endDate());l.setNotes(notes(r.notes()));l.setApprovedBy(current(a));return item(leaves.saveAndFlush(l));}
 @Transactional public Item update(Long id,Update r){LeaveRequest l=detail(id); String state=state(l, today());if("PAST".equals(state))throw new ConflictException("LEAVE_LOCKED","Un congé terminé ne peut pas être modifié."); LocalDate start=l.getStartDate(),end=l.getEndDate();if("ONGOING".equals(state)){if(r.leaveTypeId()!=null||r.startDate()!=null)throw new ConflictException("LEAVE_LOCKED","Seuls la date de fin et les notes peuvent être modifiés.");end=r.endDate()==null?end:r.endDate();}else{if(r.leaveTypeId()!=null)l.setLeaveType(type(r.leaveTypeId()));start=r.startDate()==null?start:r.startDate();end=r.endDate()==null?end:r.endDate();l.setStartDate(start);}validate(start,end,r.notes()==null?l.getNotes():r.notes()); overlap(l.getEmployee().getIdEmployee(),start,end,id);l.setEndDate(end);if(r.notes()!=null)l.setNotes(notes(r.notes()));return item(leaves.saveAndFlush(l));}
 @Transactional public void delete(Long id){LeaveRequest l=detail(id);if(!"UPCOMING".equals(state(l,today())))throw new ConflictException("LEAVE_LOCKED","Seul un congé à venir peut être supprimé.");leaves.delete(l);}
 @Transactional(readOnly=true) public Item one(Long id){return item(detail(id));}
 @Transactional(readOnly=true) public Page list(Long employeeId,Long typeId,LocalDate from,LocalDate to,String state,int page,int size,String sort){
  LocalDate today=today();
  List<String> filters=new ArrayList<>();
  MapSqlParameterSource p=new MapSqlParameterSource().addValue("today",today);
  if(employeeId!=null){filters.add("l.employee_id=:employeeId");p.addValue("employeeId",employeeId);}
  if(typeId!=null){filters.add("l.leave_type_id=:typeId");p.addValue("typeId",typeId);}
  if(from!=null){filters.add("l.end_date>=:from");p.addValue("from",from);}
  if(to!=null){filters.add("l.start_date<=:to");p.addValue("to",to);}
  if(state!=null&&!state.isBlank()){filters.add("(case when l.start_date>:today then 'UPCOMING' when l.end_date<:today then 'PAST' else 'ONGOING' end)=:state");p.addValue("state",state);}
  String where=filters.isEmpty()?"":" where "+String.join(" and ",filters);
  String select="select l.id_leave_request id,l.employee_id employee_id,concat(e.firstname,' ',e.lastname) employee_name,l.leave_type_id type_id,lt.name type_name,l.start_date,l.end_date,(l.end_date-l.start_date+1) days,case when l.start_date>:today then 'UPCOMING' when l.end_date<:today then 'PAST' else 'ONGOING' end state,l.notes,concat(u.firstname,' ',u.lastname) approved_by_name,l.created_at from leave_request l join employee e on e.id_employee=l.employee_id join leave_type lt on lt.id_leave_type=l.leave_type_id join users u on u.id_user=l.approved_by_user_id ";
  String order=" startDateAsc".equals(sort)?" order by l.start_date asc":" order by l.start_date desc";
  int limit=Math.min(100,Math.max(1,size));
  p.addValue("limit",limit).addValue("offset",Math.max(0,page)*limit);
  List<Item> items=jdbc.query(select+where+order+" limit :limit offset :offset",p,(rs,n)->new Item(rs.getLong("id"),rs.getLong("employee_id"),rs.getString("employee_name"),rs.getLong("type_id"),rs.getString("type_name"),rs.getObject("start_date",LocalDate.class),rs.getObject("end_date",LocalDate.class),rs.getLong("days"),rs.getString("state"),rs.getString("notes"),rs.getString("approved_by_name"),rs.getObject("created_at",OffsetDateTime.class)));
  String totals="select count(*) count,coalesce(sum(l.end_date-l.start_date+1),0) total_days,count(*) filter(where l.start_date<=:today and l.end_date>=:today) ongoing_count,count(*) filter(where l.start_date>:today) upcoming_count from leave_request l ";
  Map<String,Object> x=jdbc.queryForMap(totals+where,p);
  return new Page(items,new Totals(((Number)x.get("count")).longValue(),((Number)x.get("total_days")).longValue(),((Number)x.get("ongoing_count")).longValue(),((Number)x.get("upcoming_count")).longValue()),page,limit);
 }
 @Transactional(readOnly=true) public List<Overview> overview(LocalDate date){LocalDate d=date==null?today():date;String sql="select e.id_employee employee_id,concat(e.firstname,' ',e.lastname) employee_name,c.id_leave_request current_id,c.name current_name,c.start_date current_start,c.end_date current_end,p.id_leave_request last_id,p.name last_name,p.start_date last_start,p.end_date last_end,n.id_leave_request next_id,n.name next_name,n.start_date next_start,n.end_date next_end from employee e left join lateral(select l.id_leave_request,t.name,l.start_date,l.end_date from leave_request l join leave_type t on t.id_leave_type=l.leave_type_id where l.employee_id=e.id_employee and l.start_date<=:date and l.end_date>=:date limit 1)c on true left join lateral(select l.id_leave_request,t.name,l.start_date,l.end_date from leave_request l join leave_type t on t.id_leave_type=l.leave_type_id where l.employee_id=e.id_employee and l.end_date<:date order by l.end_date desc limit 1)p on true left join lateral(select l.id_leave_request,t.name,l.start_date,l.end_date from leave_request l join leave_type t on t.id_leave_type=l.leave_type_id where l.employee_id=e.id_employee and l.start_date>:date order by l.start_date asc limit 1)n on true order by e.lastname,e.firstname";return jdbc.query(sql,Map.of("date",d),(rs,n)->new Overview(rs.getLong("employee_id"),rs.getString("employee_name"),summary(rs,"current"),summary(rs,"last"),summary(rs,"next")));}
 private Summary summary(java.sql.ResultSet r,String p)throws java.sql.SQLException{
  Object rawId=r.getObject(p+"_id");
  Long id=rawId==null?null:((Number)rawId).longValue();
  return id==null?null:new Summary(id,r.getString(p+"_name"),r.getObject(p+"_start",LocalDate.class),r.getObject(p+"_end",LocalDate.class));
 }
 private LeaveRequest detail(Long id){return leaves.details(id).orElseThrow(()->new ResourceNotFoundException("Congé introuvable avec l'id "+id));} private Employee employee(Long id){return employees.findById(id).orElseThrow(()->new ResourceNotFoundException("Employé introuvable."));} private LeaveType type(Long id){return types.findById(id).orElseThrow(()->new ResourceNotFoundException("Type de congé introuvable."));} private User current(Authentication a){if(a==null)throw new ValidationException("Utilisateur connecté requis.");return users.findByUsername(a.getName()).orElseThrow(()->new ResourceNotFoundException("Utilisateur connecté introuvable."));} private LocalDate today(){return LocalDate.now(clock);} private String state(LeaveRequest l,LocalDate d){return l.getStartDate().isAfter(d)?"UPCOMING":l.getEndDate().isBefore(d)?"PAST":"ONGOING";} private void overlap(Long employee,LocalDate start,LocalDate end,Long except){leaves.overlapping(employee,start,end,except).stream().findFirst().ifPresent(l->{throw new ConflictException("LEAVE_OVERLAP","Ce congé chevauche un congé "+l.getLeaveType().getName()+" existant.",l.getStartDate(),l.getEndDate());});} private void validate(LocalDate s,LocalDate e,String n){if(s==null||e==null)throw new ValidationException("Les dates de début et de fin sont obligatoires.");if(e.isBefore(s))throw new ValidationException("La date de fin doit être postérieure ou égale au début.");if(ChronoUnit.DAYS.between(s,e)+1>366)throw new ValidationException("Un congé ne peut pas dépasser 366 jours.");if(n!=null&&n.trim().length()>1000)throw new ValidationException("Les notes ne peuvent pas dépasser 1000 caractères.");} private String notes(String n){return n==null||n.trim().isEmpty()?null:n.trim();} private String name(String n){if(n==null||n.trim().isEmpty()||n.trim().length()>50)throw new ValidationException("Le nom du type est obligatoire et limité à 50 caractères.");return n.trim();} private Item item(LeaveRequest l){return new Item(l.getId(),l.getEmployee().getIdEmployee(),l.getEmployee().getFirstName()+" "+l.getEmployee().getLastName(),l.getLeaveType().getIdLeaveType(),l.getLeaveType().getName(),l.getStartDate(),l.getEndDate(),ChronoUnit.DAYS.between(l.getStartDate(),l.getEndDate())+1,state(l,today()),l.getNotes(),l.getApprovedBy().getFirstName()+" "+l.getApprovedBy().getLastName(),l.getCreatedAt());}
}
